sys_ui_page.client_script:
/*******************************************************************************************************************************************************
  Author : Aman Jaiswal
  Description : UI Page script from performing operation on Configuration Table 
--------------------------------------------------------------------------------------------------------------------------------------------------------
  VERSION     ISSUE-NUMBER             DATE              AUTHOR                      DETAILS                                                           
   1.            -                     24-08-2019        Aman Jaiswal                                                                                                                                                                                                                                     
*******************************************************************************************************************************************************/

//display all active users
var getLookupVal = function(lookupVal){ // set lookup-value
	if(lookupVal == "user_lookup"){
		var scope = angular.element(document.getElementById('submitDefaultFields')).scope();
		scope.setUserRequired(gel(lookupVal).value);	
	}
	var groupSysId = gel(lookupVal).value;
	// 		var test = gel('sys_display'+lookupVal).value ;	
};

var authApp = angular.module("authApp",[]);
authApp.controller("authController",function ($scope,$http) {
	var arrServerCalling = ['authenticateClient','getConfigurationRecords','getConfigurationRecords','getMappingRecords'];
	var arrTblName = ['x_druva_druva_configuration','x_druva_druva_configuration','x_druva_druva_configuration','x_druva_druva_mapping'];
	$scope.setdisable = true;
	$scope.isConfigure = false;
	$scope.isMapping = false;
	$scope.modalTemplate = '';
	$scope.disableButton  = true;
	$scope.channelTypes = [];
	$scope.channelType = null;
	$scope.setResourceNameAsCI = false;

	$scope.responseParse = function(response) {
		$scope.tblName='';
		if(response!=undefined){
			var answer = response.responseXML.documentElement.getAttribute("answer");
			if(answer!==null){
				var data = JSON.parse(answer);
				if(data.hasOwnProperty("status")){
					toastr.success("Record updated successfully","Success");
				}
				else if(data.hasOwnProperty("code") || data.hasOwnProperty("error")){
					//$scope.setdisable = true;
					toastr.error("Authentication Failed","Failure");
				}
				else if(data.hasOwnProperty("access_token") && data["access_token"]!==''){
					$scope.setdisable = false;
					$scope.$apply();
					toastr.success("Authenticated successfully","Success");
				}
				else{
					$scope.mappingRecord = [];
					data.forEach(function(map) {
						switch(map.tblname){
							case 'x_druva_druva_configuration' :
								$scope.tblName = map.tblname;
								$scope.isConfigure = true;
								switch(map.key){
									case 'user':
										gel('sys_display.user_lookup').value = map.label;
										gel('user_lookup').value= map.value;
										$scope.checkUserExits = !gel('sys_display.user_lookup').value ? true :false;
										break;
									case 'userGroup':
										gel('sys_display.usergroup_lookup').value = map.label;
										gel('usergroup_lookup').value = map.value;
										break;
									case 'businessService':
										gel('business_service').value=map.value;
										gel('sys_display.business_service').value=map.label;
										break;
									case 'interval':
										$scope.hours =map.value==''? '' : Math.floor(parseInt(map.value)/60);
										$scope.minutes = map.value==''? '': parseInt(map.value)%60;
										$scope.disableButton = map.value==''?true:false;
										break;	
									case 'isActive':
										$scope.isActive = map.value =='true'?true:false;
										break;	
									case 'source':
									case 'target':
										$scope[map.key] = JSON.parse(map.value);
										break;
									case 'channelType':
										$scope.channelType = map.value || "";
										break;
									case 'setResourceNameAsCI':
										$scope.setResourceNameAsCI =
											map.value === "true" ||
											map.value === "1";
										break;
									default :	
										$scope[map.key] = map.value;
										break;
								}						
								break;
							case 'x_druva_druva_mapping':
								$scope.tblName = map.tblname;
								$scope.mappingRecord.push(map);
								$scope.isMapping = true;
								break;
						}
					});
				}
				if($scope.tblName == 'x_druva_druva_configuration'){
					$scope.impact = $scope.priority[Number($scope.impact) - 1];
					$scope.urgency = $scope.priority[Number($scope.urgency) - 1]; 
					$scope.severity = $scope.priority[Number($scope.severity) - 1];
				}
				$scope.$apply();
				$j('#loader').hide();
			}
			else{
				$j('#loader').hide();
				toastr.error("something went wrong.","error");
			}
		}
	};

	//call getConfigurationRecords() of DruvaEngine
	var durvaEngine = new GlideAjax("DruvaEngine");
	durvaEngine.addParam("sysparm_name","getConfigurationRecords");
	durvaEngine.getXML($scope.responseParse);
	$scope.priority = [
		{
			"value": 1,
			"name": "High"
		}, {
			"value": 2,
			"name": "Medium"
		}, {
			"value": 3,
			"name": "Low"
		}]; 

	$scope.loadChannelTypes = function() {
		var druvaEngine = new GlideAjax("DruvaEngine");

		druvaEngine.addParam(
			"sysparm_name",
			"getIncidentContactTypes"
		);

		druvaEngine.getXMLAnswer(function(answer) {
			var channelTypes = [];

			try {
				channelTypes = JSON.parse(answer || "[]");
			} catch (error) {
				console.error(
					"Unable to load Channel Type choices",
					error
				);
			}

			$scope.$evalAsync(function() {
				$scope.channelTypes = channelTypes;
			});
		});
	};

	// Load the dropdown values when the page opens
	$scope.loadChannelTypes();
	$scope.showModal = false;
	var setmaxGeneratedMinutes;
	var setmaxGeneratedHours;
	$scope.tab = 1;

	//called when tab changes
	$scope.tabChange = function(event, selected) {
		$scope.tab = selected;
		var durvaEngine = new GlideAjax("DruvaEngine");
		switch(selected){
			case 1:
			case 2:
			case 3:
				if(!$scope.isConfigure){
					$j('#loader').show();
					durvaEngine.addParam("sysparm_name",arrServerCalling[selected-1]);
					durvaEngine.addParam('sysparm_tableName', arrTblName[selected-1]);
					durvaEngine.getXML($scope.responseParse);
				}
				break;
			case 4:
				if(!$scope.isMapping){
					$j('#loader').show();
					durvaEngine.addParam("sysparm_name",arrServerCalling[selected-1]);
					durvaEngine.addParam('sysparm_tableName', arrTblName[selected-1]);
					durvaEngine.getXML($scope.responseParse);
				}
				break;
		}
		var parent = event.target.parentElement;
		var notes = null;
		for (var i = 0; i < parent.childNodes.length; i++) {
			if (parent.childNodes[i].className == "nav-item nav-link active") {
				notes = parent.childNodes[i];
				break;
			}
		}
		notes.setAttribute("class", "nav-item nav-link");
		event.target.setAttribute("class", "nav-item nav-link active");
	};

	//to view a secret key
	$scope.viewSecretkey = function(){
		var setSecretKeyType = document.getElementById("secretkey");
		if (setSecretKeyType.type === "password") {
			setSecretKeyType.type = "text";
		} else {
			setSecretKeyType.type = "password";
		}
	};


	//call upsertRecord() of DruvaEngine to store configuration details
	$scope.onSubmit = function(){
		$j('#loader').show();
		var durvaEngine = new GlideAjax("DruvaEngine");
		durvaEngine.addParam("sysparm_name","upsertRecord");
		durvaEngine.addParam('sysparm_tableName', 'x_druva_druva_configuration');
		var setParam = {
			"user" : user_lookup.value,
			"userGroup" : usergroup_lookup.value,
			"impact" : $scope.impact.value,
			"severity" : $scope.severity.value,
			"urgency" : $scope.urgency.value,
			"channelType": $scope.channelType || "",
			"setResourceNameAsCI": $scope.setResourceNameAsCI === true,
			"interval" : $scope.hours=="" && $scope.minutes==""?null: parseInt($scope.hours=="" ? 0: $scope.hours) * 60 + parseInt($scope.minutes=="" ? 0: $scope.minutes),
			"isActive" : $scope.isActive,
			"userName" : gel('user_lookup').value,
			"userNameLabel" : gel('sys_display.user_lookup').value,
			"userGroupName" : gel('usergroup_lookup').value,
			"userGroupLabel" : gel('sys_display.usergroup_lookup').value,
			"businessService" : gel('business_service').value,
			"businessServiceLabel" : gel('sys_display.business_service').value,
			"failureNumberSinceLastSuccess" : $scope.failureNumberSinceLastSuccess
		};

		if(!setParam.isActive){
			setParam["minGeneratedOn"] = setParam["maxGeneratedOn"] = setParam["lastRun"]= setParam["interval"] = null;
			setParam["failureNumberSinceLastSuccess"] = 0;
			$scope.hours = $scope.minutes = null;
			$scope.disableButton = true;
		}
		if(setmaxGeneratedHours || setmaxGeneratedMinutes && (setParam.user!=null && setParam.isActive)){
			setParam["maxGeneratedOn"] = $scope.lastRun;
		}
		durvaEngine.addParam('sysparm_setParam',JSON.stringify(setParam));
		durvaEngine.getXML($scope.responseParse);
	};

	//open a modal for adding a new mapping
	$scope.onNew = function(mapRecord){
		$scope.modalTemplate='';
		$scope.isReadOnly = false;
		$scope.duplicateSource = $scope.source;
		$scope.duplicateTarget = $scope.target;
		Object.keys($scope.mappingRecord).forEach(function(key){
			$scope.duplicateSource = $scope.duplicateSource.filter(function( obj ) {
				return obj.label !== $scope.mappingRecord[key].source_label;
			});
		});
		if(mapRecord!=undefined){
			$scope.isReadOnly = true;
			Object.keys($scope.source).forEach(function(key){
				if($scope.source[key].name == mapRecord.source_name){
					$scope.duplicateSource.splice(0, 0, $scope.source[key]);
				}
			});
		}
		$scope.selectedsource = $scope.duplicateSource[0];
		$scope.selectedtarget = $scope.duplicateTarget[0];
		if($scope.selectedsource==undefined){
			toastr.info("All fields are mapped","");
			return;
		}
		$scope.modalTemplate ='<div class="modal fade" id="exampleModalCenter" tabindex="-1" role="dialog" aria-labelledby="exampleModalCenterTitle" aria-hidden="true">' +
                                    '<div class="modal-dialog modal-dialog-centered modal-xl" role="document">' +
                                        '<div class="modal-content">' +
                                            '<div class="modal-header align-items-center">' +
                                                '<h2 class="modal-title" id="exampleModalCenterTitle">Incident Field Mapping</h2>' +
                                                '<button type="button" class="close" data-dismiss="modal" aria-label="Close">' +
                                                    '<span aria-hidden="true">&times;</span>' +
                                                '</button>' +
                                            '</div>' +
                                            '<div class="modal-body">' +
                                                '<div class="col-sm-12 mt-5 modal-confirmation-button">'+
                                                    '<button class="btn btn-cust-success" ng-click="save({sourcevalue: sourceValue, targetvalue: targetValue});">Save</button>'+
                                                    '<button class="btn pl-4" ng-click="cancel()">Cancel</button>'+
                                                '</div>'+
                                                '<div class="row">'+
                                                    '<div class="col-6">'+
                                                        '<label for="sourcevalue" style="font-size: 14px">Druva Alert Fields</label>'+
                                                        '<select id="sourcevalue" name="sourcevalue" ng-options="source as source.label for source in sourceval" ng-model="sourceValue" ng-disabled="setreadonly" class="custom-select"></select>'+
                                                    '</div>'+
                                                    '<div class="col-6">'+
                                                        '<div>'+
                                                        '<label for="targetvalue" style="font-size: 14px">Servicenow Fields</label>'+
                                                        '</div>'+
														'<div class="mb-5 pb-5">'+
															'<select id="targetvalue" name="targetvalue" ng-options="target as target.label for target in targetval" ng-model="targetValue" class="custom-select"></select>'+
														'</div>'+
                                                    '</div>'+
                                                '</div>'+
                                            '</div>'+
                                        '</div>' +
                                    '</div>'+
                                '</div>';
		$j('#exampleModalCenter').remove();
		$j('#exampleModalCenter').modal({
			show: 'false'
		});
	};

	//close the modal of a mapping
	$scope.close = function(){
		$j("#exampleModalCenter").modal("hide");
	};

	//call authenticateClient() of DruvaEngine used to check a valid client and secret key  if its valid than store it into a configuration table
	$scope.authenticate = function(){
		$j('#loader').show();
		var durvaEngine = new GlideAjax("DruvaEngine");
		durvaEngine.addParam("sysparm_name","authenticateClient");
		durvaEngine.addParam('sysparm_tableName', 'x_druva_druva_configuration');
		var setParam = {
			"client_key":$scope.clientid,
			"secret_key":$scope.secretkey,
			"condition":'type,Auth',
			"uidatasource":true
		};
		durvaEngine.addParam('sysparm_setParam',JSON.stringify(setParam));
		durvaEngine.getXML($scope.responseParse);
	};

	//call upsertRecord() of DruvaEngine to store mapping  details in the mapping table
	$scope.saveMapping = function(sourcevalue, targetvalue){
		$j('#loader').show();
		var durvaEngine = new GlideAjax("DruvaEngine");
		durvaEngine.addParam("sysparm_name","upsertRecord");
		durvaEngine.addParam('sysparm_tableName', 'x_druva_druva_mapping');
		var setParam = {
			"source":sourcevalue,
			"target":targetvalue
		};
		durvaEngine.addParam('sysparm_setParam',angular.toJson(setParam));
		durvaEngine.getXML($scope.responseParse);
		$j("#exampleModalCenter").modal("hide");
	};

	//open a confirmation modal to delete a mapping record
	$scope.confirmDeleteModal = function(mapRecord){
		$scope.modalTemplate='';
		$scope.deleteRec = mapRecord;
		$scope.modalTemplate='<div class="modal fade" id="exampleModalCenter" tabindex="-1" role="dialog" aria-labelledby="exampleModalCenterTitle" aria-hidden="true">' +
			'<div class="modal-dialog modal-dialog-centered modal-xl delete" role="document">' +
			'<div class="modal-content">' +
			'<div class="modal-header">' +
			'<h5 class="modal-title" id="exampleModalCenterTitle" style="text-align: center">Delete Record</h5>' +
			'<button type="button" class="close" data-dismiss="modal" aria-label="Close">' +
			'<span aria-hidden="true">&times;</span>' +
			'</button>' +
			'</div>' +
			'<div class="modal-body text-center">' +
			'Are you sure?'+
			'</div>'+  
			'<div class="col-sm-12 text-center pb-3">'+
			'<button class="btn btn-cust-success" ng-click="deleterecord({mapRecord:record});">Ok</button>'+
			'<button class="btn pl-4" ng-click="cancel()">Cancel</button>'+
			'</div>'+
			'</div>' +
			'</div>' +
			'</div>';
		$j('#exampleModalCenter').remove();
		$j('#exampleModalCenter').modal({
			show: 'false'
		});
	};

	// call deleteRecord() of DruvaEngine to delete mapping record in the mapping table
	$scope.deleteMapping = function(mapRecord){
		$j('#loader').show();
		var strArr = Object.toJSON(mapRecord);
		var durvaEngine = new GlideAjax("DruvaEngine");
		durvaEngine.addParam('sysparm_array', strArr);
		durvaEngine.addParam("sysparm_name","deleteRecord");
		durvaEngine.addParam('sysparm_tableName', 'x_druva_druva_mapping');
		var setParam = {
			"rec":mapRecord
		};
		durvaEngine.addParam('sysparm_setParam',JSON.stringify(setParam));
		durvaEngine.getXML($scope.responseParse);
		$j("#exampleModalCenter").modal("hide");
	};
	$scope.$watch("hours", function (newValue, oldValue) {
		setmaxGeneratedHours = true;
	});
	$scope.$watch("minutes", function (newValue, oldValue) {
		setmaxGeneratedMinutes = true;
	});

	//check mandatory fields of scheduler interval (ie Hours and Minutes) if its less than 0
	$scope.checkSchedulerInterval = function(){
		$scope.disableButton = $scope.showErrorMsg = parseInt(!$scope.hours ? 0: $scope.hours) * 60 + parseInt(!$scope.minutes ? 0: $scope.minutes) ==0;
	};

	//set mandatory fields for user
	$scope.setUserRequired = function(userValue) {	
		$scope.checkUserExits = $scope.setUserError = !userValue ? true : false;
		$scope.$apply();
	};
});
authApp.directive('modal', function ($compile) {
	return {
		restrict: 'E',
		scope: {
			modal:'=',
			targetval: '=',
			targetValue:'=target',
			sourceval: '=',
			sourceValue:'=source',
			setreadonly:'=',
			deleterecord:'&',
			record:'=',
			save:'&',
			cancel:'&'
		},
		link: function(scope, ele, attrs) {
			scope.$watch('modal', function(newValue, oldValue) {
				if(newValue){
					ele.html(scope.modal);
					$compile(ele.contents())(scope);
					$j('#exampleModalCenter').modal({
						show: 'false'
					});
					scope.modal='';
				}
			});
		},
		controller: function ($scope) {
		}
	};
});
